SELECT DISTINCTROW qryLetztesAnodenrecoating.[Max von Rücklieferdatum], Montage.[Einschalt Datum], qryLetztesAnodenrecoating.[Max von Rücklieferdatum], Montage.[Element Nr], Montage.[Anoden Nr], Montage.[Kathoden Nr], Montage.Membrantyp, Montage.[Membran Nr], Montage.[Elektroden Abstand], Montage.[Montage Datum], Montage.Remarks, Montage.Elektrolyseur, Montage.Position, Montage.[Ausschalt Datum], Montage.DOL, Montage.[Demontage Datum], Montage.Gruppe, Montage.Abschaltgrund, Montage.[Anode Coating], Montage.[Anode Electrode], Montage.[Anode Shell], Montage.[Cathode Coating], Montage.[Cathode Electrode], Montage.[Cathode Shell], Montage.[Info Membrane]
FROM Montage LEFT JOIN qryLetztesAnodenrecoating ON Montage.[Anoden Nr] = qryLetztesAnodenrecoating.Anodennummer
WHERE (((qryLetztesAnodenrecoating.[Max von Rücklieferdatum]) Is Null)) OR (((Montage.[Einschalt Datum])>[Max von Rücklieferdatum]));
